<?php
require_once __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../../includes/functions.php'; require_admin('../login.php');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $name = post_string('name'); $type = post_string('type') === 'date' ? 'date' : 'service'; $slug = slugify(post_string('slug') ?: $name); $short_description = post_string('short_description'); $description = post_string('description'); $status = post_string('status') === 'inactive' ? 'inactive' : 'active'; $is_featured = isset($_POST['is_featured']) ? 1 : 0; if ($name === '' || strlen($name) > 150 || $slug === '' || strlen($slug) > 180 || $short_description === '' || strlen($short_description) > 255 || $description === '') { flash('error', 'Enter valid name, slug, short description, and description values.'); } elseif (service_slug_exists($pdo, $slug)) { flash('error', 'That slug is already in use. Choose another one.'); } else { $image = upload_service_image($_FILES['image'] ?? null); if (uploaded_file_was_submitted($_FILES['image'] ?? null) && $image === null) { flash('error', 'Upload a JPG, PNG, or WebP image up to 2 MB.'); } else { try { $statement = $pdo->prepare('INSERT INTO services (name, type, slug, short_description, description, image, status, is_featured) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'); $statement->execute([$name, $type, $slug, $short_description, $description, $image, $status, $is_featured]); flash('success', 'Service created.'); redirect('index.php'); } catch (PDOException $exception) { delete_service_image($image); flash('error', 'The service could not be saved. Check that the slug is unique.'); } } } }
$page_title = 'Add service'; require __DIR__ . '/../includes/header.php';
?><div class="admin-title"><h1>Add service</h1></div><form class="admin-card admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Name<input name="name" required value="<?= e($_POST['name'] ?? '') ?>"></label><label>Type<select name="type"><option value="date" <?= ($_POST['type'] ?? '') === 'date' ? 'selected' : '' ?>>Date</option><option value="service" <?= ($_POST['type'] ?? 'service') === 'service' ? 'selected' : '' ?>>Service</option></select></label><label>Slug<input name="slug" value="<?= e($_POST['slug'] ?? '') ?>" placeholder="Generated from name if blank"></label><label>Short description<input name="short_description" required value="<?= e($_POST['short_description'] ?? '') ?>"></label><label>Description<textarea name="description" rows="7" required><?= e($_POST['description'] ?? '') ?></textarea></label><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?= ($_POST['status'] ?? '') === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label><label><input type="checkbox" name="is_featured" <?= isset($_POST['is_featured']) ? 'checked' : '' ?>> Feature on the home page</label><button class="button" type="submit">Create service <span>↗</span></button></form><?php require __DIR__ . '/../includes/footer.php'; ?>